<?php
require dirname(__DIR__).'/_init.php';use App\Core\AccessControl;use App\Core\Database;use App\Core\CSRF;
AccessControl::require('payments.manage');$db=Database::connection();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){CSRF::verify();try{$cid=(int)$_POST['consultation_id'];$q=$db->prepare("SELECT patient_id FROM consultations WHERE id=?");$q->execute([$cid]);$patient=$q->fetchColumn();if(!$patient)throw new RuntimeException('Consultation not found.');$amount=(float)$_POST['amount'];if($amount<=0)throw new RuntimeException('Amount must be greater than zero.');$receipt='CC-R'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$db->prepare("INSERT INTO payments(receipt_number,patient_id,consultation_id,amount,payment_method,received_by) VALUES(?,?,?,?,?,?)")->execute([$receipt,$patient,$cid,$amount,$_POST['payment_method'],$_SESSION['user']['id']]);header('Location: /payments/index.php');exit;}catch(Throwable $e){$err=$e->getMessage();}}
$consults=$db->query("SELECT c.id,p.patient_number,p.full_name,c.consulted_at FROM consultations c JOIN patients p ON p.id=c.patient_id ORDER BY c.id DESC")->fetchAll();$fee=$db->query("SELECT setting_value FROM settings WHERE setting_key='consultation_fee'")->fetchColumn();require dirname(__DIR__).'/_layout_top.php';?>
<h2>Record payment</h2><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><form method="post" class="card p-4"><?=CSRF::field()?><label class="form-label">Consultation</label><select class="form-select mb-3" name="consultation_id" required><option value="">Select consultation</option><?php foreach($consults as $c):?><option value="<?=$c['id']?>"><?=e($c['patient_number'].' - '.$c['full_name'].' ('.$c['consulted_at'].')')?></option><?php endforeach;?></select><label class="form-label">Amount (MWK)</label><input class="form-control mb-3" type="number" min="1" step="0.01" name="amount" value="<?=e((string)$fee)?>" required><label class="form-label">Payment method</label><select class="form-select mb-3" name="payment_method"><option>Cash</option><option>Mobile Money</option><option>Bank</option></select><button class="btn btn-primary">Save payment</button></form><?php require dirname(__DIR__).'/_layout_bottom.php';?>
